"use client"

import { ThemeProvider as NextThemesProvider } from "next-themes"
import type { ComponentProps } from "react"

import { ThemePreferenceSync } from "./theme.use-sync-preferences"

export type ThemeProviderProps = ComponentProps<typeof NextThemesProvider> & {
	/** When true, writes theme changes into preferences localStorage via `applyThemePreference`. */
	syncPreferences?: boolean
}

export function ThemeProvider({
	attribute = "class",
	defaultTheme = "system",
	enableSystem = true,
	disableTransitionOnChange = true,
	syncPreferences = true,
	children,
	...props
}: ThemeProviderProps) {
	return (
		<NextThemesProvider
			attribute={attribute}
			defaultTheme={defaultTheme}
			enableSystem={enableSystem}
			disableTransitionOnChange={disableTransitionOnChange}
			{...props}>
			{syncPreferences ? <ThemePreferenceSync /> : null}
			{children}
		</NextThemesProvider>
	)
}

"use client"

import { Moon, Sun } from "lucide-react"
import { useTheme } from "next-themes"
import type { ComponentProps } from "react"
import { useSyncExternalStore } from "react"

import { Button } from "@/components/ui/button"
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip"
import { cn } from "@/lib/utils"

type ThemeToggleProps = {
	className?: string
	size?: ComponentProps<typeof Button>["size"]
	variant?: ComponentProps<typeof Button>["variant"]
	tooltip?: string
}

const emptySubscribe = () => () => {}

function useMounted() {
	return useSyncExternalStore(emptySubscribe, () => true, () => false)
}

export function ThemeToggle({
	className,
	size = "icon",
	variant = "ghost",
	tooltip,
}: ThemeToggleProps) {
	const { resolvedTheme, setTheme } = useTheme()
	const mounted = useMounted()

	const isDark = resolvedTheme === "dark"
	const label = isDark ? "Switch to light theme" : "Switch to dark theme"
	const ariaLabel = tooltip ?? (mounted ? label : "Toggle theme")

	const button = (
		<Button
			aria-label={ariaLabel}
			className={cn(variant === "ghost" && "text-muted-foreground hover:text-foreground", className)}
			onClick={() => {
				if (!mounted) return
				setTheme(isDark ? "light" : "dark")
			}}
			size={size}
			type="button"
			variant={variant}>
			{mounted ? (
				isDark ? (
					<Sun className="size-4" />
				) : (
					<Moon className="size-4" />
				)
			) : (
				<span aria-hidden className="size-4" />
			)}
		</Button>
	)

	if (!tooltip) {
		return button
	}

	return (
		<Tooltip>
			<TooltipTrigger asChild>{button}</TooltipTrigger>
			<TooltipContent>{tooltip}</TooltipContent>
		</Tooltip>
	)
}

"use client"

import { useTheme } from "next-themes"
import { applyThemePreference } from "@/lib/feature-kit/preferences"
import type { ThemePreference } from "@/lib/feature-kit/preferences"
import { useEffect } from "react"

function toThemePreference(theme: string | undefined): ThemePreference | undefined {
	if (theme === "light" || theme === "dark" || theme === "system") {
		return theme
	}
	return undefined
}

/** Mirrors next-themes changes into the preferences storage key (no DOM mutation). */
export function ThemePreferenceSync() {
	const { theme } = useTheme()

	useEffect(() => {
		const pref = toThemePreference(theme)
		if (pref) {
			applyThemePreference(pref)
		}
	}, [theme])

	return null
}

import type { AppPreferences } from "../schema/schema-app-preferences"

import { applyLocalePreference } from "./apply-locale"
import { applyThemePreference } from "./apply-theme"

/** Run all paint-critical preference appliers (browser). */
export function applyAppPreferences(prefs: AppPreferences) {
  applyThemePreference(prefs.theme)
  applyLocalePreference(prefs.locale)
}

import type { PrefsLocale } from "../cookie/cookie-prefs-constants"

import { PREFS_RTL_LOCALES } from "../cookie/cookie-prefs-constants"

/** Apply locale to <html lang/dir> before paint (browser only). */
export function applyLocalePreference(locale: PrefsLocale | undefined) {
  if (typeof document === "undefined" || !locale) return

  document.documentElement.lang = locale
  document.documentElement.dir = PREFS_RTL_LOCALES.includes(locale) ? "rtl" : "ltr"
}

import type { ThemePreference } from "../schema/schema-app-preferences"

import { THEME_STORAGE_KEY } from "../cookie/cookie-prefs-constants"

/**
 * Sync next-themes localStorage only.
 * DOM `dark` class is owned by SSR + PreferenceBootstrapScript + next-themes —
 * mutating it here during persist/hydration causes cross-app FOUC.
 */
export function applyThemePreference(theme: ThemePreference | undefined) {
  if (typeof document === "undefined" || !theme) return

  try {
    localStorage.setItem(THEME_STORAGE_KEY, theme)
  } catch {
    // Private browsing / storage disabled.
  }
}

"use client"

import type { PrefsLocale } from "../cookie/cookie-prefs-constants"
import type { ThemePreference } from "../schema/schema-app-preferences"

import { useSyncExternalStore } from "react"

import {
  LEGACY_LOCALE_COOKIE_NAME,
  LEGACY_THEME_COOKIE_NAME,
  PREFS_COOKIE_NAME,
  PREFS_LOCALES,
  PREFS_RTL_LOCALES,
  THEME_STORAGE_KEY,
} from "../cookie/cookie-prefs-constants"

type PreferenceBootstrapScriptProps = {
  /** Server-resolved theme for this HTML response — applied before cookie reads. */
  theme?: ThemePreference
  /** Active `[lang]` locale for this HTML response. */
  locale?: PrefsLocale | string
  /**
   * Parent domain the prefs cookie is written to (NEXT_PUBLIC_COOKIE_DOMAIN),
   * so hosts outside this origin — the IdP login page — can read the theme.
   * Unset keeps the cookie host-only.
   */
  cookieDomain?: string | undefined
}

const emptySubscribe = () => () => {}

/**
 * Blocking anti-FOUC bootstrap for theme + locale.
 *
 * React 19 warns when a `<script>` is created during a client render (scripts in
 * components never execute on the client). Emit the inline script only on the
 * server render and the matching hydration pass; return `null` afterward.
 * By then the IIFE has already run from the SSR HTML, so theme/locale stay applied.
 */
export function PreferenceBootstrapScript({ theme, locale, cookieDomain }: PreferenceBootstrapScriptProps = {}) {
  const shouldRenderScript = useSyncExternalStore(
    emptySubscribe,
    () => false,
    () => true,
  )

  if (!shouldRenderScript) return null

  return (
    <script
      id="feature-kit-preference-bootstrap"
      // biome-ignore lint/security/noDangerouslySetInnerHtml: static anti-FOUC bootstrap from known constants only.
      dangerouslySetInnerHTML={{ __html: buildBootstrapScript(theme, locale, cookieDomain) }}
    />
  )
}

function buildBootstrapScript(serverTheme?: ThemePreference, serverLocale?: string, cookieDomain?: string): string {
  const serverThemeJson = JSON.stringify(serverTheme ?? null)
  const serverLocaleJson = JSON.stringify(serverLocale ?? null)
  const cookieDomainJson = JSON.stringify(cookieDomain ?? null)

  return `(function(){try{var prefsName=${JSON.stringify(PREFS_COOKIE_NAME)},themeName=${JSON.stringify(LEGACY_THEME_COOKIE_NAME)},localeName=${JSON.stringify(LEGACY_LOCALE_COOKIE_NAME)},themeKey=${JSON.stringify(THEME_STORAGE_KEY)},locales=${JSON.stringify([...PREFS_LOCALES])},rtl=${JSON.stringify([...PREFS_RTL_LOCALES])},serverTheme=${serverThemeJson},serverLocale=${serverLocaleJson},cookieDomain=${cookieDomainJson};if(cookieDomain)window.__AIQ_PREFS_COOKIE_DOMAIN__=cookieDomain;function readCookie(n){var m=document.cookie.match(new RegExp("(?:^|;\\s*)"+n+"=([^;]+)"));return m?decodeURIComponent(m[1]):null}function applyTheme(theme){if(!theme)return;try{localStorage.setItem(themeKey,theme)}catch(e){}var dark=theme==="dark"||(theme==="system"&&window.matchMedia("(prefers-color-scheme: dark)").matches);document.documentElement.classList.toggle("dark",dark);document.documentElement.classList.toggle("theme-brand",theme==="brand");document.documentElement.style.colorScheme=dark?"dark":"light"}function applyLocale(locale){if(!locale||locales.indexOf(locale)<0)return;document.documentElement.lang=locale;document.documentElement.dir=rtl.indexOf(locale)>=0?"rtl":"ltr"}var prefs={};var raw=readCookie(prefsName);if(raw){try{prefs=JSON.parse(raw)||{}}catch(e){prefs={}}}var theme=serverTheme;if(theme!=="brand"&&theme!=="light"&&theme!=="dark"&&theme!=="system"){theme=prefs.theme;if(theme!=="brand"&&theme!=="light"&&theme!=="dark"&&theme!=="system"){theme=readCookie(themeName);if(theme!=="brand"&&theme!=="light"&&theme!=="dark"&&theme!=="system")theme=null}}var locale=serverLocale;if(!locale||locales.indexOf(locale)<0){locale=prefs.locale;if(!locale||locales.indexOf(locale)<0){locale=readCookie(localeName);if(!locale||locales.indexOf(locale)<0)locale=null}}applyTheme(theme);applyLocale(locale);if(cookieDomain){var sec=location.protocol==="https:";var rescope=function(n,v){if(!v)return;document.cookie=n+"=; path=/; max-age=0";document.cookie=n+"="+encodeURIComponent(v)+"; path=/; max-age=31536000; samesite=lax; domain="+cookieDomain+(sec?"; secure":"")};rescope(themeName,theme);rescope(prefsName,raw);rescope(localeName,locale)}}catch(e){}})();`
}

/** Shared origin cookie bag for cross-app user preferences (theme, locale, formats…). */

export const PREFS_COOKIE_NAME = "aiq-prefs"

/** Legacy per-pref cookies — still read/mirrored during migration. */
export const LEGACY_THEME_COOKIE_NAME = "aiq-theme"
export const LEGACY_LOCALE_COOKIE_NAME = "NEXT_LOCALE"

/** next-themes localStorage key — must stay in sync with theme package. */
export const THEME_STORAGE_KEY = "theme"

const ONE_YEAR_SECONDS = 60 * 60 * 24 * 365

export const sharedPrefsCookie = {
  name: PREFS_COOKIE_NAME,
  path: "/",
  maxAge: ONE_YEAR_SECONDS,
  sameSite: "lax" as const,
} as const

/**
 * Locales known to the portal (keep in sync with `feature/i18n` `locales`).
 * Bootstrap script embeds this list for pre-paint lang/dir.
 */
export const PREFS_LOCALES = ["en-IN", "hi-IN", "ur-IN", "en-US", "en-GB"] as const

export type PrefsLocale = (typeof PREFS_LOCALES)[number]

/** RTL locales — keep in sync with i18n language direction config. */
export const PREFS_RTL_LOCALES: readonly PrefsLocale[] = ["ur-IN"]

import {
  type AppPreferences,
  isPrefsLocale,
  isThemePreference,
  mergeAppPreferences,
  parseAppPreferences,
} from "../schema/schema-app-preferences"
import { LEGACY_LOCALE_COOKIE_NAME, LEGACY_THEME_COOKIE_NAME, PREFS_COOKIE_NAME } from "./cookie-prefs-constants"

function readCookieValue(cookieHeader: string | null | undefined, name: string): string | null {
  if (!cookieHeader) return null

  for (const part of cookieHeader.split(";")) {
    const trimmed = part.trim()
    const separator = trimmed.indexOf("=")
    if (separator === -1) continue

    if (trimmed.slice(0, separator).trim() !== name) continue
    return decodeURIComponent(trimmed.slice(separator + 1))
  }

  return null
}

/** Read + parse `aiq-prefs`, falling back to legacy theme/locale cookies. */
export function readAppPreferencesFromCookieHeader(cookieHeader: string | null | undefined): AppPreferences {
  const raw = readCookieValue(cookieHeader, PREFS_COOKIE_NAME)
  let prefs: AppPreferences = {}

  if (raw) {
    try {
      prefs = parseAppPreferences(JSON.parse(raw))
    } catch {
      prefs = {}
    }
  }

  if (!prefs.theme) {
    const legacyTheme = readCookieValue(cookieHeader, LEGACY_THEME_COOKIE_NAME)
    if (isThemePreference(legacyTheme)) {
      prefs = mergeAppPreferences(prefs, { theme: legacyTheme })
    }
  }

  if (!prefs.locale) {
    const legacyLocale = readCookieValue(cookieHeader, LEGACY_LOCALE_COOKIE_NAME)
    if (isPrefsLocale(legacyLocale)) {
      prefs = mergeAppPreferences(prefs, { locale: legacyLocale })
    }
  }

  return prefs
}

export function readAppPreferencesFromDocumentCookie(): AppPreferences {
  if (typeof document === "undefined") return {}
  return readAppPreferencesFromCookieHeader(document.cookie)
}

import {
  type AppPreferences,
  mergeAppPreferences,
  preferencesEqual,
  serializeAppPreferences,
} from "../schema/schema-app-preferences"
import {
  LEGACY_LOCALE_COOKIE_NAME,
  LEGACY_THEME_COOKIE_NAME,
  PREFS_COOKIE_NAME,
  sharedPrefsCookie,
} from "./cookie-prefs-constants"
import { readAppPreferencesFromDocumentCookie } from "./cookie-prefs-read"

declare global {
  interface Window {
    /** Set by PreferenceBootstrapScript from NEXT_PUBLIC_COOKIE_DOMAIN. */
    __AIQ_PREFS_COOKIE_DOMAIN__?: string | undefined
  }
}

function buildCookieParts(name: string, value: string): string {
  const secure = typeof window !== "undefined" && window.location.protocol === "https:"
  const parts = [
    `${name}=${encodeURIComponent(value)}`,
    `path=${sharedPrefsCookie.path}`,
    `max-age=${sharedPrefsCookie.maxAge}`,
    `samesite=${sharedPrefsCookie.sameSite}`,
  ]

  if (typeof window !== "undefined" && window.location.hostname === "localhost") {
    parts.push("domain=localhost")
  } else {
    // Preferences are shared with hosts outside this origin — notably the IdP,
    // which reads the theme so the login page matches the portal the user came
    // from. Without a domain the cookie is host-only and never reaches it.
    //
    // Sourced from NEXT_PUBLIC_COOKIE_DOMAIN via the bootstrap script rather
    // than derived from the hostname: guessing a parent domain gets
    // `example.co.uk` wrong, and a domain the browser rejects drops the cookie
    // entirely. Unset means host-only, i.e. exactly the previous behaviour.
    const shared = typeof window !== "undefined" ? window.__AIQ_PREFS_COOKIE_DOMAIN__ : undefined
    if (shared) parts.push(`domain=${shared}`)
  }

  if (secure) {
    parts.push("secure")
  }

  return parts.join("; ")
}

/**
 * Merge `patch` into the current bag and write `aiq-prefs` (+ legacy mirrors).
 * Returns the merged bag. Idempotent when already equal.
 */
export function writeAppPreferencesToDocumentCookie(patch: AppPreferences): AppPreferences {
  if (typeof document === "undefined") return patch

  const current = readAppPreferencesFromDocumentCookie()
  const merged = mergeAppPreferences(current, patch)
  if (preferencesEqual(current, merged)) {
    return merged
  }

  // biome-ignore lint/suspicious/noDocumentCookie: sync cookie write required before cross-app navigation / OAuth redirects.
  document.cookie = buildCookieParts(PREFS_COOKIE_NAME, serializeAppPreferences(merged))

  // Mirror legacy cookies so next-intl / existing theme SSR keep working during migration.
  if (merged.theme) {
    // biome-ignore lint/suspicious/noDocumentCookie: legacy theme mirror
    document.cookie = buildCookieParts(LEGACY_THEME_COOKIE_NAME, merged.theme)
  }
  if (merged.locale) {
    // biome-ignore lint/suspicious/noDocumentCookie: legacy NEXT_LOCALE mirror
    document.cookie = buildCookieParts(LEGACY_LOCALE_COOKIE_NAME, merged.locale)
  }

  return merged
}

import { NextResponse } from "next/server"

import { readAppPreferencesFromCookieHeader } from "../cookie/cookie-prefs-read"
import { mergeAppPreferences, parseAppPreferences } from "../schema/schema-app-preferences"
import { writeAppPreferencesCookies } from "./persist-prefs.server"

/**
 * POST /api/prefs
 * Merges the JSON body into the shared `aiq-prefs` bag (and legacy mirrors).
 */
export async function POST(req: Request) {
  let body: unknown
  try {
    body = await req.json()
  } catch {
    return NextResponse.json({ ok: false, message: "Invalid JSON" }, { status: 400 })
  }

  const patch = parseAppPreferences(body)
  if (Object.keys(patch).length === 0) {
    return NextResponse.json({ ok: false, message: "No valid preferences" }, { status: 400 })
  }

  const current = readAppPreferencesFromCookieHeader(req.headers.get("cookie"))
  const merged = mergeAppPreferences(current, patch)

  const response = NextResponse.json({ ok: true, prefs: merged })
  writeAppPreferencesCookies(response, merged)
  return response
}

import { applyAppPreferences } from "../apply/apply-all"
import { readAppPreferencesFromDocumentCookie } from "../cookie/cookie-prefs-read"
import { writeAppPreferencesToDocumentCookie } from "../cookie/cookie-prefs-write"
import { type AppPreferences, mergeAppPreferences, preferencesEqual } from "../schema/schema-app-preferences"

function resolveApiPrefix(basePath = ""): string {
  if (basePath && basePath !== "/") {
    return basePath.replace(/\/$/, "")
  }

  if (typeof window === "undefined") return ""

  const segments = window.location.pathname.split("/").filter(Boolean)
  const first = segments[0]
  // Locale-looking first segment (xx-XX) → no app basePath prefix.
  if (first && !/^[a-z]{2}-[A-Z]{2}$/.test(first) && first !== "api") {
    return `/${first}`
  }

  return ""
}

/** Sync merge + cookie write + paint apply + localStorage sync. Returns merged bag. */
export function persistAppPreferences(patch: AppPreferences): AppPreferences {
  if (typeof document === "undefined") return patch

  const merged = writeAppPreferencesToDocumentCookie(patch)
  applyAppPreferences(merged)

  try {
    localStorage.setItem("app-preferences", JSON.stringify(merged))
  } catch {
    // Ignore quota errors
  }

  return merged
}

/** Sync cookie first, then optional POST /api/prefs for SSR Set-Cookie. */
export async function persistAppPreferencesOnServer(patch: AppPreferences, basePath = "") {
  if (typeof window === "undefined") return

  const before = readAppPreferencesFromDocumentCookie()
  const alreadyMatched = preferencesEqual(mergeAppPreferences(before, patch), before)

  persistAppPreferences(patch)
  if (alreadyMatched) return

  const prefix = resolveApiPrefix(basePath)

  try {
    const response = await fetch(`${prefix}/api/prefs`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(patch),
      credentials: "same-origin",
    })
    if (!response.ok) return
  } catch {
    // Client cookie remains the fallback when the route is unavailable.
  }
}

import type { NextResponse } from "next/server"

import { cookies } from "next/headers"

import {
  LEGACY_LOCALE_COOKIE_NAME,
  LEGACY_THEME_COOKIE_NAME,
  PREFS_COOKIE_NAME,
  sharedPrefsCookie,
} from "../cookie/cookie-prefs-constants"
import {
  type AppPreferences,
  isPrefsLocale,
  isThemePreference,
  mergeAppPreferences,
  parseAppPreferences,
  serializeAppPreferences,
  type ThemePreference,
} from "../schema/schema-app-preferences"

/** Match portal/host: explicit COOKIE_SECURE wins, else production default. */
function resolveCookieSecure(): boolean {
  const raw = process.env["COOKIE_SECURE"]
  if (raw === "true" || raw === "1") return true
  if (raw === "false" || raw === "0") return false
  return process.env["NODE_ENV"] === "production"
}

function prefsCookieOptions() {
  const isLocalStart = process.env["LOCAL_START"] === "1" || process.env["NODE_ENV"] === "development"
  return {
    path: sharedPrefsCookie.path,
    maxAge: sharedPrefsCookie.maxAge,
    sameSite: sharedPrefsCookie.sameSite,
    // Local multi-port apps use http://localhost — Secure cookies would be dropped.
    secure: isLocalStart ? false : resolveCookieSecure(),
    ...(isLocalStart ? { domain: "localhost" as const } : {}),
  }
}

export async function getAppPreferencesFromCookies(): Promise<AppPreferences> {
  const cookieStore = await cookies()
  let prefs: AppPreferences = {}

  const raw = cookieStore.get(PREFS_COOKIE_NAME)?.value
  if (raw) {
    try {
      prefs = parseAppPreferences(JSON.parse(raw))
    } catch {
      prefs = {}
    }
  }

  if (!prefs.theme) {
    const legacyTheme = cookieStore.get(LEGACY_THEME_COOKIE_NAME)?.value
    if (isThemePreference(legacyTheme)) {
      prefs = mergeAppPreferences(prefs, { theme: legacyTheme })
    }
  }

  if (!prefs.locale) {
    const legacyLocale = cookieStore.get(LEGACY_LOCALE_COOKIE_NAME)?.value
    if (isPrefsLocale(legacyLocale)) {
      prefs = mergeAppPreferences(prefs, { locale: legacyLocale })
    }
  }

  return prefs
}

export async function getPreferredThemeFromPrefs(): Promise<ThemePreference> {
  const prefs = await getAppPreferencesFromCookies()
  return prefs.theme ?? "brand"
}

export async function setAppPreferencesCookies(patch: AppPreferences) {
  const cookieStore = await cookies()
  const current = await getAppPreferencesFromCookies()
  const merged = mergeAppPreferences(current, patch)
  const options = prefsCookieOptions()

  cookieStore.set(PREFS_COOKIE_NAME, serializeAppPreferences(merged), options)
  if (merged.theme) {
    cookieStore.set(LEGACY_THEME_COOKIE_NAME, merged.theme, options)
  }
  if (merged.locale) {
    cookieStore.set(LEGACY_LOCALE_COOKIE_NAME, merged.locale, options)
  }
}

/** Write the full merged bag (+ legacy mirrors) onto a NextResponse. */
export function writeAppPreferencesCookies(response: NextResponse, merged: AppPreferences) {
  const options = prefsCookieOptions()
  response.cookies.set(PREFS_COOKIE_NAME, serializeAppPreferences(merged), options)
  if (merged.theme) {
    response.cookies.set(LEGACY_THEME_COOKIE_NAME, merged.theme, options)
  }
  if (merged.locale) {
    response.cookies.set(LEGACY_LOCALE_COOKIE_NAME, merged.locale, options)
  }
}

import { PREFS_LOCALES, type PrefsLocale } from "../cookie/cookie-prefs-constants"

/**
 * Add a preference checklist:
 * 1. Add an optional field here + validate in `parseAppPreferences`.
 * 2. Add `apply-<name>.ts` and wire it into `apply-all` / the bootstrap IIFE.
 * 3. Merge via `persistAppPreferences({ … })` on change (sync cookie first).
 *
 * VALIDATION IS NOT OPTIONAL. Every value here reaches `Intl.*` constructors via
 * `packages/format`, and `Intl` throws `RangeError` on an unrecognised option
 * rather than ignoring it. The bag is parsed from the `aiq-prefs` cookie, which
 * is client-written — so an unvalidated field is a render crash reachable by
 * editing a cookie. `parseAppPreferences` drops anything it cannot vouch for.
 */
export type ThemePreference = "brand" | "light" | "dark" | "system"

export type DateTimeStyle = "full" | "long" | "medium" | "short"
export type HourCycle = "h11" | "h12" | "h23" | "h24"
export type FirstDayOfWeek = 0 | 1 | 2 | 3 | 4 | 5 | 6

export const DATE_TIME_STYLES: readonly DateTimeStyle[] = ["full", "long", "medium", "short"]
export const HOUR_CYCLES: readonly HourCycle[] = ["h11", "h12", "h23", "h24"]

export type AppPreferences = {
  theme?: ThemePreference
  locale?: PrefsLocale
  timezone?: string
  currency?: string
  numberingSystem?: string
  calendar?: string
  firstDayOfWeek?: FirstDayOfWeek
  dateStyle?: DateTimeStyle
  timeStyle?: DateTimeStyle
  hourCycle?: HourCycle
}

/** Patch bag — explicit `undefined` means "leave existing value" (see `mergeAppPreferences`). */
export type AppPreferencesPatch = {
  [K in keyof AppPreferences]?: AppPreferences[K] | undefined
}

export function isThemePreference(value: unknown): value is ThemePreference {
  return value === "brand" || value === "light" || value === "dark" || value === "system"
}

export function isPrefsLocale(value: unknown): value is PrefsLocale {
  return typeof value === "string" && (PREFS_LOCALES as readonly string[]).includes(value)
}

export function isDateTimeStyle(value: unknown): value is DateTimeStyle {
  return typeof value === "string" && (DATE_TIME_STYLES as readonly string[]).includes(value)
}

export function isHourCycle(value: unknown): value is HourCycle {
  return typeof value === "string" && (HOUR_CYCLES as readonly string[]).includes(value)
}

export function isFirstDayOfWeek(value: unknown): value is FirstDayOfWeek {
  return typeof value === "number" && Number.isInteger(value) && value >= 0 && value <= 6
}

/**
 * `Intl.supportedValuesOf` is the authoritative list but is comparatively slow
 * and allocates a fresh array per call, and this parse runs on every request
 * that reads the cookie. Build the sets once, lazily, and only if the runtime
 * has the API — Node 24 and current browsers do; the `undefined` fallback keeps
 * older runtimes on the probe path below rather than rejecting everything.
 */
function supportedSet(key: "calendar" | "numberingSystem"): ReadonlySet<string> | undefined {
  const supportedValuesOf = (Intl as { supportedValuesOf?: (k: string) => string[] }).supportedValuesOf
  if (typeof supportedValuesOf !== "function") return undefined

  try {
    return new Set(supportedValuesOf(key).map((entry) => entry.toLowerCase()))
  } catch {
    return undefined
  }
}

let calendarSet: ReadonlySet<string> | undefined | null = null
let numberingSystemSet: ReadonlySet<string> | undefined | null = null

/**
 * Zone validity is checked by CONSTRUCTION, not against
 * `Intl.supportedValuesOf("timeZone")` — that list holds only canonical IDs, so
 * ICU's `Asia/Calcutta` is present while the modern `Asia/Kolkata` is not. Every
 * alias (`America/Buenos_Aires`, `Asia/Saigon`, …) would be rejected the same
 * way. `Intl.DateTimeFormat` accepts aliases and throws exactly where a later
 * format call would, which is the failure we are guarding against.
 *
 * Results are memoised because this runs per request, and the cache is bounded
 * because the input is a forgeable cookie — otherwise unique hostile values
 * would grow it without limit.
 */
const TIME_ZONE_CACHE_LIMIT = 256
const timeZoneCache = new Map<string, boolean>()

export function isTimeZone(value: unknown): value is string {
  if (typeof value !== "string" || value.length === 0 || value.length > 64) return false

  const cached = timeZoneCache.get(value)
  if (cached !== undefined) return cached

  let valid: boolean
  try {
    new Intl.DateTimeFormat(undefined, { timeZone: value })
    valid = true
  } catch {
    valid = false
  }

  if (timeZoneCache.size >= TIME_ZONE_CACHE_LIMIT) timeZoneCache.clear()
  timeZoneCache.set(value, valid)
  return valid
}

export function isCurrencyCode(value: unknown): value is string {
  return typeof value === "string" && /^[A-Za-z]{3}$/.test(value)
}

export function isNumberingSystem(value: unknown): value is string {
  if (typeof value !== "string" || !/^[a-z0-9]{3,8}$/i.test(value)) return false

  if (numberingSystemSet === null) numberingSystemSet = supportedSet("numberingSystem")
  if (numberingSystemSet) return numberingSystemSet.has(value.toLowerCase())

  try {
    new Intl.NumberFormat(undefined, { numberingSystem: value } as Intl.NumberFormatOptions)
    return true
  } catch {
    return false
  }
}

export function isCalendar(value: unknown): value is string {
  if (typeof value !== "string" || !/^[a-z0-9-]{3,20}$/i.test(value)) return false

  if (calendarSet === null) calendarSet = supportedSet("calendar")
  if (calendarSet) return calendarSet.has(value.toLowerCase())

  try {
    new Intl.DateTimeFormat(undefined, { calendar: value } as Intl.DateTimeFormatOptions)
    return true
  } catch {
    return false
  }
}

/** Parse unknown JSON into a sanitized preference bag (drops invalid fields). */
export function parseAppPreferences(value: unknown): AppPreferences {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    return {}
  }

  const record = value as Record<string, unknown>
  const prefs: AppPreferences = {}

  if (isThemePreference(record["theme"])) {
    prefs.theme = record["theme"]
  }
  if (isPrefsLocale(record["locale"])) {
    prefs.locale = record["locale"]
  }
  if (isTimeZone(record["timezone"])) {
    prefs.timezone = record["timezone"]
  }
  if (isCurrencyCode(record["currency"])) {
    prefs.currency = record["currency"].toUpperCase()
  }
  if (isNumberingSystem(record["numberingSystem"])) {
    prefs.numberingSystem = record["numberingSystem"]
  }
  if (isCalendar(record["calendar"])) {
    prefs.calendar = record["calendar"]
  }
  if (isFirstDayOfWeek(record["firstDayOfWeek"])) {
    prefs.firstDayOfWeek = record["firstDayOfWeek"]
  }
  if (isDateTimeStyle(record["dateStyle"])) {
    prefs.dateStyle = record["dateStyle"]
  }
  if (isDateTimeStyle(record["timeStyle"])) {
    prefs.timeStyle = record["timeStyle"]
  }
  if (isHourCycle(record["hourCycle"])) {
    prefs.hourCycle = record["hourCycle"]
  }

  return prefs
}

export function mergeAppPreferences(base: AppPreferences, patch: AppPreferencesPatch): AppPreferences {
  return {
    ...base,
    ...Object.fromEntries(Object.entries(patch).filter(([, v]) => v !== undefined)),
  }
}

export function serializeAppPreferences(prefs: AppPreferences): string {
  return JSON.stringify(prefs)
}

export function preferencesEqual(a: AppPreferences, b: AppPreferences): boolean {
  return (
    a.theme === b.theme &&
    a.locale === b.locale &&
    a.timezone === b.timezone &&
    a.currency === b.currency &&
    a.numberingSystem === b.numberingSystem &&
    a.calendar === b.calendar &&
    a.firstDayOfWeek === b.firstDayOfWeek &&
    a.dateStyle === b.dateStyle &&
    a.timeStyle === b.timeStyle &&
    a.hourCycle === b.hourCycle
  )
}
